// @ts-check
// check-subtype-map.mjs — verifies that taxonomy-v2.ts SUB_TYPE_TO_V2 matches
// the canonical testdata/legacy_subtype_map.json from the API package.
//
// Run: node scripts/check-subtype-map.mjs
//
// This script is the TS side of §3.5 (single source of truth for subtype mapping).
// The JSON file is generated by: go run ./cmd/gen-parity-snapshot (in api/)

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, "..");
const apiRoot = path.join(root, "..", "api");

// Load the canonical JSON source
const jsonPath = path.join(apiRoot, "internal", "taxonomy", "testdata", "legacy_subtype_map.json");
if (!fs.existsSync(jsonPath)) {
  console.error(`ERROR: canonical mapping not found at ${jsonPath}`);
  console.error("Generate it with: cd api && go run ./cmd/gen-parity-snapshot");
  process.exit(1);
}

const canonical = JSON.parse(fs.readFileSync(jsonPath, "utf8"));

// Read the TS file and extract SUB_TYPE_TO_V2 entries via regex
// (avoids running tsc — works with plain Node)
const tsPath = path.join(root, "components", "site-wizard", "taxonomy-v2.ts");
const tsSource = fs.readFileSync(tsPath, "utf8");

// Extract all  "SubType": ["archetype", "industry.id"]  entries from the TS const
const entryRe = /"([^"]+)":\s*\["([^"]+)",\s*"([^"]+)"\]/g;
const tsMap = {};
let m;
while ((m = entryRe.exec(tsSource)) !== null) {
  // Only capture entries inside SUB_TYPE_TO_V2 (before INDUSTRY_ID_TO_V1)
  if (m.index > tsSource.indexOf("INDUSTRY_ID_TO_V1")) break;
  tsMap[m[1]] = [m[2], m[3]];
}

const errors = [];

// JSON → TS direction
for (const [subType, v2] of Object.entries(canonical)) {
  const tsVal = tsMap[subType];
  if (!tsVal) {
    errors.push(`JSON has "${subType}" but taxonomy-v2.ts SUB_TYPE_TO_V2 does not`);
    continue;
  }
  if (tsVal[0].toLowerCase() !== v2[0].toLowerCase()) {
    errors.push(`"${subType}": archetype mismatch — JSON="${v2[0]}" TS="${tsVal[0]}"`);
  }
  if (tsVal[1].toLowerCase() !== v2[1].toLowerCase()) {
    errors.push(`"${subType}": industry_id mismatch — JSON="${v2[1]}" TS="${tsVal[1]}"`);
  }
}

// TS → JSON direction
for (const subType of Object.keys(tsMap)) {
  if (!canonical[subType]) {
    errors.push(`taxonomy-v2.ts has "${subType}" but testdata/legacy_subtype_map.json does not`);
  }
}

if (errors.length > 0) {
  console.error(`\ncheck-subtype-map: ${errors.length} error(s) found:\n`);
  errors.forEach((e) => console.error(`  ✗ ${e}`));
  console.error(
    "\nTo fix: update taxonomy-v2.ts AND api/internal/modules/aisite/adaptor_compat.go to match," +
    "\nthen regenerate: cd api && go run ./cmd/gen-parity-snapshot"
  );
  process.exit(1);
} else {
  console.log(`check-subtype-map: OK — ${Object.keys(canonical).length} entries match`);
}
